  'n1-107': { ja: '[彼|かれ]は[病気|びょうき]を[口実|こうじつ]に[会議|かいぎ]を[休|やす]んだ。', zh: '他以生病為藉口沒參加會議。' },
  'n1-108': { ja: '[彼|かれ]に[弁明|べんめい]の[機会|きかい]が[与|あた]えられた。', zh: '他獲得了辯解的機會。' },
  'n1-109': { ja: 'それは[単|たん]なる[詭弁|きべん]にすぎない。', zh: '那只不過是詭辯罷了。' },
  'n1-110': { ja: '[社長|しゃちょう]の[失踪|しっそう]は[大|おお]きな[騒|さわ]ぎになった。', zh: '社長失蹤引起了很大的騷動。' },
  'n1-111': { ja: '[彼|かれ]は[脅迫|きょうはく]の[手紙|てがみ]を[受け取|うけと]った。', zh: '他收到了恐嚇信。' },
