  'n1-113': { ja: '[社長|しゃちょう]は[贈賄|ぞうわい]の[容疑|ようぎ]で[調|しら]べられた。', zh: '社長因涉嫌行賄而接受調查。' },
  'n1-114': { ja: '[経理|けいり]の[社員|しゃいん]が[会社|かいしゃ]の[金|きん]を[横領|おうりょう]していた。', zh: '會計部的員工侵佔了公司的錢。' },
