  'n1-118': { ja: '[会議|かいぎ]の[前|まえ]に[十分|じゅうぶん]な[根回|ねまわ]しをしておいた。', zh: '會議前先做好了充分的疏通。' },
  'n1-119': { ja: '[専門|せんもん][家|か]の[見地|けんち]から[意見|いけん]を[述|の]べる。', zh: '從專家的觀點發表意見。' },
  'n1-120': { ja: '[景気|けいき][回復|かいふく]の[兆|きざ]しが[見|み]えてきた。', zh: '景氣開始出現復甦的徵兆。' },
  'n1-121': { ja: '[彼|かれ]らは[銀行|ぎんこう][強盗|ごうとう]を[企|くわだ]てていた。', zh: '他們企圖搶銀行。' },
  'n1-122': { ja: '[人|ひと]の[失敗|しっぱい]を[嘲|あざけ]るべきではない。', zh: '不應該嘲笑別人的失敗。' },
  'n1-123': { ja: '[誰|だれ]も[彼|かれ]の[失敗|しっぱい]を[咎|とが]めなかった。', zh: '沒有人責備他的失敗。' },
  'n1-124': { ja: '[彼|かれ]は[体裁|ていさい]を[繕|つくろ]おうとした。', zh: '他試圖粉飾門面。' },
  'n1-125': { ja: '[記憶|きおく]を[手繰|たぐ]って、あの[夜|よる]のことを[思い出|おもいだ]した。', zh: '追溯記憶，想起了那一晚的事。' },
  'n1-126': { ja: '[古|ふる]い[記録|きろく]を[紐解|ひもと]くと、[真相|しんそう]が[見|み]えてきた。', zh: '翻閱舊紀錄後，真相逐漸浮現。' },
  'n1-127': { ja: '[新|あたら]しい[証拠|しょうこ]で[彼|かれ]のアリバイが[揺|ゆ]らいだ。', zh: '新證據讓他的不在場證明動搖了。' },
  'n1-128': { ja: '[裁判所|さいばんしょ]は[彼|かれ]の[訴|うった]えを[退|しりぞ]けた。', zh: '法院駁回了他的訴訟。' },
  'n1-129': { ja: '[大雪|おおゆき]が[捜索|そうさく]を[阻|はば]んだ。', zh: '大雪阻礙了搜索。' },
  'n1-130': { ja: '[彼|かれ]は[笑|わら]って[質問|しつもん]を[誤魔化|ごまか]した。', zh: '他笑著把問題矇混過去。' },
  'n1-131': { ja: '[彼|かれ]は[辞任|じにん]を[仄|ほの]めかした。', zh: '他暗示自己要辭職。' },
