  'n1-136': { ja: 'それは[甚|はなは]だしい[誤解|ごかい]だ。', zh: '那是極大的誤解。' },
  'n1-137': { ja: '[白々|しらじら]しい[嘘|うそ]はすぐにばれる。', zh: '明顯的謊話馬上就會被拆穿。' },
  'n1-138': { ja: '[事故|じこ]の[生々|なまなま]しい[記憶|きおく]が[残|のこ]っている。', zh: '還留有事故的鮮明記憶。' },
  'n1-139': { ja: '[現場|げんば]は[物々|ものもの]しい[雰囲気|ふんいき]に[包|つつ]まれていた。', zh: '現場籠罩在森嚴的氣氛中。' },
  'n1-140': { ja: '[犯行|はんこう]は[綿密|めんみつ]に[計画|けいかく]されていた。', zh: '犯罪行為經過綿密的計畫。' },
  'n1-141': { ja: '[彼|かれ]は[怪訝|けげん]な[顔|かお]でわたしを[見|み]た。', zh: '他一臉詫異地看著我。' },
  'n1-142': { ja: '[犯人|はんにん]は[狡猾|こうかつ]な[手段|しゅだん]で[逃|に]げ[続|つづ]けた。', zh: '犯人用狡猾的手段持續逃亡。' },
  'n1-143': { ja: '[彼女|かのじょ]は[冷徹|れいてつ]な[目|め]で[状況|じょうきょう]を[分析|ぶんせき]した。', zh: '她以冷靜透徹的眼光分析狀況。' },
  'n1-144': { ja: '[端的|たんてき]に[言|い]えば、[計画|けいかく]は[失敗|しっぱい]だ。', zh: '直截了當地說，計畫失敗了。' },
  'n1-145': { ja: 'あなたを[疑|うたが]うつもりは[毛頭|もうとう]ない。', zh: '我絲毫沒有懷疑你的意思。' },
  'n1-146': { ja: '[予|あらかじ]めご[了承|りょうしょう]ください。', zh: '敬請事先諒解。' },
