  'n1-148': { ja: '[今年|ことし]の[夏|なつ]は[殊|こと]に[暑|あつ]い。', zh: '今年夏天尤其熱。' },
  'n1-149': { ja: '[捜査|そうさ]は[粛々|しゅくしゅく]と[進|すす]められた。', zh: '搜查默默地進行著。' },
  'n1-150': { ja: '[一人|ひとり]の[努力|どりょく]が、ひいては[社会|しゃかい]を[変|か]える。', zh: '一個人的努力，進而能改變社會。' },
