  'n1-154': { ja: 'その[決定|けってい]に[異議|いぎ]を[唱|とな]えた。', zh: '對那個決定提出了異議。' },
  'n1-155': { ja: 'このような[結果|けっか]になり、[誠|まこと]に[遺憾|いかん]です。', zh: '變成這種結果，實在很遺憾。' },
  'n1-156': { ja: '[彼|かれ]は[意地|いじ]を[張|は]って[謝|あやま]らなかった。', zh: '他賭氣不肯道歉。' },
  'n1-157': { ja: 'これは[調査|ちょうさ]の[一環|いっかん]として[行|おこな]われた。', zh: '這是作為調查的一環而進行的。' },
