  'n1-163': { ja: '[資料|しりょう]の[閲覧|えつらん]には[許可|きょか]が[必要|ひつよう]だ。', zh: '閱覽資料需要許可。' },
  'n1-164': { ja: 'ここで[会|あ]えたのも[何|なに]かの[縁|えん]だ。', zh: '能在這裡相遇也是一種緣分。' },
