  'n1-169': { ja: '[計画|けいかく]の[概略|がいりゃく]を[説明|せつめい]します。', zh: '說明計畫的概要。' },
  'n1-170': { ja: '[二人|ふたり]の[間|あいだ]には[長年|ながねん]の[確執|かくしつ]があった。', zh: '兩人之間長年不和。' },
  'n1-171': { ja: '[技術|ぎじゅつ]の[革新|かくしん]が[社会|しゃかい]を[変|か]えた。', zh: '技術革新改變了社會。' },
  'n1-172': { ja: '[探偵|たんてい]は[事件|じけん]の[核心|かくしん]に[迫|せま]った。', zh: '偵探逼近了事件的核心。' },
