  'n1-193': { ja: '[彼|かれ]は[恵|めぐ]まれない[境遇|きょうぐう]で[育|そだ]った。', zh: '他在困苦的境遇中長大。' },
  'n1-194': { ja: '[彼|かれ]の[記憶|きおく][力|りょく]は[驚異|きょうい][的|てき]だ。', zh: '他的記憶力驚人。' },
