  'n1-200': { ja: '[苦心|くしん]の[末|すえ]、ついに[完成|かんせい]した。', zh: '費盡苦心，終於完成了。' },
  'n1-201': { ja: '[最新|さいしん]の[技術|ぎじゅつ]を[駆使|くし]して[捜査|そうさ]した。', zh: '運用最新技術進行搜查。' },
  'n1-202': { ja: '[彼|かれ]はいつも[仕事|しごと]の[愚痴|ぐち]を[言|い]っている。', zh: '他總是在抱怨工作。' },
  'n1-203': { ja: '[誰|だれ]かが[部屋|へや]に[入|はい]った[形跡|けいせき]がある。', zh: '有人進過房間的跡象。' },
  'n1-204': { ja: 'この[事件|じけん]は[社会|しゃかい]に[警鐘|けいしょう]を[鳴|な]らした。', zh: '這起事件為社會敲響了警鐘。' },
  'n1-205': { ja: '[罪|つみ]を[犯|おか]せば[刑罰|けいばつ]を[受|う]ける。', zh: '犯了罪就要受刑罰。' },
  'n1-206': { ja: '[二人|ふたり]は[結託|けったく]して[会社|かいしゃ]の[金|きん]を[盗|ぬす]んだ。', zh: '兩人勾結盜取了公司的錢。' },
  'n1-207': { ja: '[彼|かれ]は[大|おお]きな[決断|けつだん]を[下|くだ]した。', zh: '他做出了重大的決定。' },
  'n1-208': { ja: '[安全|あんぜん][面|めん]での[懸念|けねん]が[残|のこ]る。', zh: '安全方面仍有疑慮。' },
  'n1-209': { ja: '[彼|かれ]はこの[分野|ぶんや]の[権威|けんい]だ。', zh: '他是這個領域的權威。' },
  'n1-210': { ja: '[仮説|かせつ]を[検証|けんしょう]する[必要|ひつよう]がある。', zh: '有必要驗證假說。' },
  'n1-211': { ja: '[迷|まよ]ったときは[原点|げんてん]に[戻|もど]ろう。', zh: '迷惘時就回到原點吧。' },
