  'n1-1879': { ja: '[観客|かんきゃく]は[熱狂|ねっきょう]の[渦|うず]に[包|つつ]まれた。', zh: '觀眾被捲入狂熱的漩渦中。' },
  'n1-1880': { ja: '[彼|かれ]は[寝食|しんしょく]を[忘|わす]れて[研究|けんきゅう]に[没頭|ぼっとう]した。', zh: '他廢寢忘食地埋首研究。' },
