  'n1-2052': { ja: '[万物|ばんぶつ]は[流転|るてん]する。', zh: '萬物皆在流轉。' },
  'n1-2053': { ja: '[森羅万象|しんらばんしょう]に[神|かみ]が[宿|やど]ると[考|かんが]えられた。', zh: '人們認為萬物皆有神靈寄宿。' },
