  'n1-2058': { ja: '[理不尽|りふじん]な[要求|ようきゅう]には[応|おう]じられない。', zh: '無法答應蠻不講理的要求。' },
  'n1-2059': { ja: '[人間|にんげん]は[時|とき]に[非合理|ひごうり]な[行動|こうどう]をとる。', zh: '人類有時會做出非理性的行為。' },
  'n1-2060': { ja: '[証言|しょうげん]の[整合性|せいごうせい]を[確認|かくにん]する。', zh: '確認證詞前後是否吻合。' },
