  'n1-2086': { ja: '[彼|かれ]は[死|し]んだ[妻|つま]の[幻影|げんえい]を[見|み]た。', zh: '他看到了亡妻的幻影。' },
  'n1-2087': { ja: '[彼|かれ]は[全|ぜん][社員|しゃいん]の[模範|もはん]となる[人物|じんぶつ]だ。', zh: '他是全體員工的模範人物。' },
  'n1-2088': { ja: '[成功|せいこう]の[尺度|しゃくど]は[人|ひと]それぞれだ。', zh: '成功的衡量標準因人而異。' },
